import { Component, Element, Host, Prop, h } from "@stencil/core";
import { internationalization } from "../../utils/i18n/translations";
import { searchResultGroupInterface } from "../global-search/global-search";
import { searchResultItemInterface } from "../global-search/global-search";
import translations from "./i18n";

/**
 * @since 1.1.30
 *
 * @data-testid global-search__result-badge-tooltip - The tooltip shown for truncated result-count badges.
 * @data-testid global-search__result-badge - The result-count badge for a result group.
 * @data-testid global-search__result-link-{id} - A result link row, where `{id}` is the result item's id.
 * @data-testid global-search__show-all-{groupId} - The action that expands the full result group, where `{groupId}` is the group id.
 */
@Component({
	tag: "hbr-global-search-group",
	styleUrl: "global-search-group.scss",
	shadow: true,
})
export class HbrGlobalSearchGroup {
	@Element() host: HTMLHbrGlobalSearchGroupElement;

	@Prop() groupConfig: searchResultGroupInterface;

	@Prop() showMore = false;

	@Prop() noPadding = false;

	@Prop() showCount = false;

	// Used for search result text highlight
	@Prop() queryText = "";

	/**
	 * The limit of results shown in the initial results view.
	 */
	@Prop() limit = 5;

	// Used for search result text highlight
	@Prop() selectedItem = "";

	/**
	 * Callback that will be invoked when a user selects a search result.
	 */
	@Prop() selectResultHandler: (item: searchResultItemInterface) => void;

	/**
	 * Callback that will be invoked when a user selects a search result.
	 */
	@Prop() showAllClickHandler: (groupId: string) => void;

	onSearchItemClick = (item) => {
		this.selectResultHandler(item);
	};

	onShowMoreClick = () => {
		this.showAllClickHandler(this.groupConfig.id);
	};

	handleSearchKeyDown = (event) => {
		if (event.key === "Enter" && this.selectedItem === "show_all") {
			this.onShowMoreClick();
		}
	};

	componentWillLoad() {
		window.addEventListener("keydown", this.handleSearchKeyDown, true);
	}

	render() {
		const numOfResults = this.groupConfig.resultItems.length;
		const resultItems =
			numOfResults > this.limit && !this.showMore
				? this.groupConfig.resultItems.slice(0, this.limit)
				: this.groupConfig.resultItems;

		const BadgeStyle = {
			"--text-color": "var(--base-text-default)",
			"margin-left": "12px",
		};

		return (
			<Host>
				<slot />
				<div
					part="group"
					class={`
            search-group
            ${this.noPadding ? "search-group-no-padding" : ""}
          `}
				>
					<div part="groupTopArea" class="search-group__top-area">
						<div part="groupTitle" class="search-group__title">
							{this.groupConfig.title}
						</div>
						{this.showCount &&
							(numOfResults > 99 ? (
								<hbr-tooltip
									data-testid="global-search__result-badge-tooltip"
									content="There more than 100 results, please be more specific for searching."
									placement="right"
								>
									<hbr-badge
										size="small"
										pill={true}
										style={BadgeStyle}
										data-testid="global-search__result-badge"
									>
										99+
									</hbr-badge>
								</hbr-tooltip>
							) : (
								<hbr-badge
									size="small"
									pill={true}
									style={BadgeStyle}
									data-testid="global-search__result-badge"
								>
									{numOfResults}
								</hbr-badge>
							))}
					</div>
					<div part="groupItems" class="search-group__items">
						{resultItems.map((item) => {
							return (
								<div
									part="item"
									class={`search-group__item
                    ${
											item.id === this.selectedItem
												? "search-group__item-selected"
												: ""
										}`}
									onClick={() => {
										this.selectedItem !== item.id &&
											this.onSearchItemClick(item);
									}}
									data-testid={
										item.testId
											? item.testId
											: item.id
											  ? `global-search--result-item-${item.id}`
											  : `global-search--result-item-${item.title
														.toLowerCase()
														.split(" ")
														.join("-")}`
									}
								>
									<div part="itemTitle" class="search-group__item-title">
										<hbr-highlight
											text={item.title}
											queryText={this.queryText}
											caseSensitive={false}
										/>
									</div>
								</div>
							);
						})}
					</div>
					{numOfResults > this.limit && !this.showMore && (
						<div
							part="showmore"
							class={`search-group__show-more hbr-type-link
                    ${
											this.selectedItem === "show_all"
												? "search-group__show-more-focused"
												: ""
										}`}
							onClick={this.onShowMoreClick}
							data-testid={
								this.groupConfig.id &&
								`global-search-group--show-more--${this.groupConfig.id}`
							}
						>
							{internationalization(translations, "moreResults")}
						</div>
					)}
				</div>
			</Host>
		);
	}
}
